DROP DATABASE IF EXISTS company_powerbi;
CREATE DATABASE company_powerbi;
USE company_powerbi;

CREATE TABLE Departments (DepartmentID INT PRIMARY KEY, DepartmentName VARCHAR(50), Location VARCHAR(50), ManagerName VARCHAR(100), DepartmentBudget DECIMAL(14,2));
CREATE TABLE Employees (EmployeeID INT PRIMARY KEY, EmployeeName VARCHAR(100), Gender VARCHAR(10), Age INT, DepartmentID INT, JobTitle VARCHAR(60), HireDate DATE, Salary DECIMAL(12,2), PerformanceScore INT, ExperienceYears INT, EmploymentStatus VARCHAR(20), City VARCHAR(50), Region VARCHAR(30), FOREIGN KEY (DepartmentID) REFERENCES Departments(DepartmentID));
CREATE TABLE Products (ProductID INT PRIMARY KEY, ProductName VARCHAR(100), Category VARCHAR(50), SubCategory VARCHAR(50), UnitCost DECIMAL(10,2), UnitPrice DECIMAL(10,2));
CREATE TABLE Customers (CustomerID INT PRIMARY KEY, CustomerName VARCHAR(100), Gender VARCHAR(10), Age INT, City VARCHAR(50), Region VARCHAR(30), CustomerSegment VARCHAR(30));
CREATE TABLE Sales (SaleID INT PRIMARY KEY, SaleDate DATE, EmployeeID INT, ProductID INT, CustomerID INT, Quantity INT, UnitPrice DECIMAL(10,2), Discount DECIMAL(5,2), Revenue DECIMAL(14,2), Profit DECIMAL(14,2), FOREIGN KEY (EmployeeID) REFERENCES Employees(EmployeeID), FOREIGN KEY (ProductID) REFERENCES Products(ProductID), FOREIGN KEY (CustomerID) REFERENCES Customers(CustomerID));

